head.script:
scwin.gVar = {
    "cInvalidMessage" : "",
    "cDisplaymessage" : "",
    "cFailCause" : "",
    "cInvalidMessageFunc" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > invalidMessage]<br/>입력값에 대한 유효성 체크를 통과하지 못한 경우 표시될 메시지를 설정합니다.",
    "validation" : [
        "displaymessage=true 이고 validate() 메소드의 실행 결과가 실패일때 동작합니다.",
        "invalidMessageFunc 속성이 설정되면 해당 속성은 무시됩니다.",
        "유효성 체크를 통과하지 못한 경우 표시될 메시지를 설정합니다.",
        "속성값을 설정하지 않으면 시스템 기본 메시지가 적용됩니다.",
        "validate() 메소드는 자동으로 실행되지 않으므로 스크립트로 직접 실행해야 합니다.",
        "설정된 메시지는 alert() 메소드로 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_displaymessage.setValue("2");
    con_failCause.setValue("minlength");
    con_invalidMessageFunc.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 invalidMessage 는 위 조건에서 직접 입력합니다. 실패 원인 속성은 선택한 1개만 적용되고 (mandatory=true / minlength=10 / maxlength=3), Target 재생성 시 초기값은 mandatory 선택 시 빈값으로, 그 외에는 secret (6자) 으로 설정됩니다\n[절차] invalidMessage, displaymessage, 실패 원인 속성 (필요 시 invalidMessageFunc) 선택 -> Target 재생성 -> validate 버튼 클릭 (maxlength 는 target1 입력값을 건드리지 말고 그대로 클릭 - 직접 입력하면 maxlength 제한에 잘려 초과 값을 만들 수 없음)\n[확인] Target 재생성 직후에는 alert 이 뜨지 않고 validate 버튼을 눌러야 뜨는지, alert 창 문구 (설정한 invalidMessage / 시스템 기본 메시지 / invalidMessageFunc 반환값), 결과창의 validate() 반환값"', '', 'label1');

    // 조건 설정
    scwin.gVar["cInvalidMessage"] = con_invalidMessage.getValue();
    scwin.gVar["cDisplaymessage"] = con_displaymessage.getText();
    scwin.gVar["cFailCause"] = con_failCause.getValue();
    scwin.gVar["cInvalidMessageFunc"] = con_invalidMessageFunc.getText();

    let properties = {
        invalidMessage : scwin.gVar["cInvalidMessage"],
        displaymessage : scwin.gVar["cDisplaymessage"],
        invalidMessageFunc : scwin.gVar["cInvalidMessageFunc"],
    }

    // 유효성 체크 실패를 유발할 원인 속성 (선택한 1개만 적용)
    if (scwin.gVar["cFailCause"] === "mandatory")
        properties.mandatory = "true";
    else if (scwin.gVar["cFailCause"] === "minlength")
        properties.minlength = "10";
    else if (scwin.gVar["cFailCause"] === "maxlength")
        properties.maxlength = "3";

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList);

    // mandatory 원인은 값이 비어야 실패하므로 생성 직후 헬퍼가 넣은 초기값을 빈값으로 덮음 (minlength, maxlength 는 초기값 secret 유지)
    if (scwin.gVar["cFailCause"] === "mandatory")
        target1.setValue("");
}



// validate 실행 (invalidMessage 발동 수단) - validation 1 ~ 6 판정 출력
scwin.btn_validate_onclick = function (e) {
    // password 는 화면으로 글자 수 확인이 불가하므로 판정 근거로 값 길이를 함께 출력
    let nLength = (target1.getValue() || "").length;
    let rtn = target1.validate();

    let strInvalidMessage = (scwin.gVar["cInvalidMessage"] === "") ? "미설정" : scwin.gVar["cInvalidMessage"];
    let strDisplaymessage = (scwin.gVar["cDisplaymessage"] === "") ? "미설정" : scwin.gVar["cDisplaymessage"];
    let strInvalidMessageFunc = (scwin.gVar["cInvalidMessageFunc"] === "") ? "미설정" : scwin.gVar["cInvalidMessageFunc"];

    wf_body_bottom.getObj("scwin").setReturnValue("invalidMessage " + strInvalidMessage + " / displaymessage " + strDisplaymessage + " / 실패 원인 " + scwin.gVar["cFailCause"] + " / invalidMessageFunc " + strInvalidMessageFunc + " / target1 값 길이 " + nLength + " -> validate() 반환값 : " + rtn);
}



// invalidMessageFunc 로 설정되는 사용자 정의 메시지 함수
scwin.fn_msg = function () {
    return "invalidMessageFunc 메시지 (원인 : " + this.getType() + ")";
}
